function App() {
  return (
    <SidebarProvider>
      <Stack direction="row" gap="lg" align="start">
        <Sidebar>
          <Sidebar.Header>
            <Logo />
            <span>Acme App</span>
          </Sidebar.Header>
          <Sidebar.Nav>
            <Sidebar.Section>
              <Sidebar.Item icon={<HomeIcon />} active>Dashboard</Sidebar.Item>
              <Sidebar.Item icon={<ChartIcon />}>Analytics</Sidebar.Item>
            </Sidebar.Section>
          </Sidebar.Nav>
        </Sidebar>
        <MainContent />
      </Stack>
    </SidebarProvider>
  );
}

function MainContent() {
  const { toggleSidebar, state } = useSidebar();

  return (
    <Stack gap="sm" align="start">
      <Text scale="sm" color="secondary">State: {state}</Text>
      <Button size="sm" variant="soft" onClick={toggleSidebar}>
        Toggle sidebar
      </Button>
    </Stack>
  );
}

